                    else -> showHelp()
                }
            }
            args[0] == "query" && args.size > 1 && args[1] == "--help" -> showCommandHelp("query")
            args[0] == "query" && args.size > 1 && args[1] == "servers" && args.any { it == "--help" || it == "-h" } -> showCommandHelp("query-servers")
