                if (parentCommand != null) {
                    System.err.println()
                    System.err.println("Did you mean: secman $parentCommand ${args.joinToString(" ")}")
                    System.err.println()
                }

                showHelp()
                1
            }
        }
    }

    private fun runPicocli(command: Class<*>, args: Array<String>): Int =
        createCliContext().use { context ->
            PicocliRunner.execute(command, context, *args.drop(1).toTypedArray())
        }

    private fun showHelp(): Int {
        println("""
            secman - Security Requirement and Risk Assessment Management CLI

            Usage: secman <command> [options]
                   secman help <command>       Show detailed help for a command

            Commands:
              CrowdStrike:
                query                  Query CrowdStrike vulnerabilities for a single host
                query servers          Batch query and import server vulnerabilities
            status to errorBody
        } catch (e: Exception) {
            log.error("POST {} error: {}", url, e.message)
            -1 to null
        }
    }

    fun putMapWithStatus(url: String, body: Any, authToken: String): Pair<Int, Map<*, *>?> {
        val request = HttpRequest.PUT(url, body)
            .header("Authorization", "Bearer $authToken")
            .contentType(MediaType.APPLICATION_JSON)

        return try {
            val response = httpClient.toBlocking().exchange(request, Map::class.java)
            response.status.code to response.body()
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            val status = e.status.code
            val errorBody = try {
                e.response.getBody(Map::class.java).orElse(null)
            } catch (_: Exception) {
                null
            }
            log.warn("PUT {} returned {}: {}", url, status, e.message)
            status to errorBody
        } catch (e: Exception) {
            log.error("PUT {} error: {}", url, e.message)
            -1 to null
        }
    }

    /**
     * Send a DELETE request with JWT authentication, returning both the HTTP
     * status code and the parsed body (mirrors postMapWithStatus/putMapWithStatus).
     */
    fun deleteWithStatus(url: String, authToken: String): Pair<Int, Map<*, *>?> {
        val request = HttpRequest.DELETE<Any>(url)
            .header("Authorization", "Bearer $authToken")

        return try {
            val response = httpClient.toBlocking().exchange(request, Map::class.java)
            response.status.code to response.body()
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            val status = e.status.code
            val errorBody = try {
                e.response.getBody(Map::class.java).orElse(null)
            } catch (_: Exception) {
                null
            }
            log.warn("DELETE {} returned {}: {}", url, status, e.message)
            status to errorBody
        } catch (e: Exception) {
            log.error("DELETE {} error: {}", url, e.message)
            -1 to null
        }
    }

    /**
     * Send a POST request returning raw string body
     */
    fun postString(url: String, body: Any, authToken: String): String? {
        val request = HttpRequest.POST(url, body)
            .header("Authorization", "Bearer $authToken")
            .contentType(MediaType.APPLICATION_JSON)

        return try {
            val response = httpClient.toBlocking().exchange(request, String::class.java)
            response.body()
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            log.error("POST {} failed: {} - {}", url, e.status.code, e.message)
            null
        } catch (e: Exception) {
            log.error("POST {} error: {}", url, e.message)
            null
        }
    }

    /**
     * Send a GET request returning a list of maps (for array responses)
     */
    @Suppress("UNCHECKED_CAST")
    fun getList(url: String, authToken: String): List<Map<String, Any?>>? {
        val request = HttpRequest.GET<Any>(url)
            .header("Authorization", "Bearer $authToken")
            .accept(MediaType.APPLICATION_JSON)

        return try {
            val response = httpClient.toBlocking().exchange(request, String::class.java)
            val body = response.body() ?: return null
            objectMapper.readValue(body, List::class.java) as? List<Map<String, Any?>>
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            log.error("GET {} failed: {} - {}", url, e.status.code, e.message)
            null
        } catch (e: Exception) {
            log.error("GET {} error: {}", url, e.message)
            null
        }
    }

    fun getObjectMapper(): ObjectMapper = objectMapper
}
package com.secman.service

import com.secman.domain.User
import com.secman.repository.UserRepository
import io.micronaut.serde.annotation.Serdeable
import jakarta.inject.Singleton
import jakarta.transaction.Transactional
import org.hibernate.exception.ConstraintViolationException
import org.slf4j.LoggerFactory
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder
import java.util.UUID

/**
 * Resolves a user by id or email, lazy-creating a real User row when an
 * email is given but no matching User exists yet (a "pending" user known
 * only via PENDING UserMapping rows).
 *
 * Extracted from AwsAccountSharingService.resolveUser so all save paths
 * (workgroup membership, risk assessment assignees, AWS sharing) share
 * the same materialization behavior.
 *
 * IMPORTANT: When a new User is created here we apply pending UserMappings
 * SYNCHRONOUSLY in the current transaction. We deliberately do NOT publish
 * UserCreatedEvent — see the inline comment for the Hibernate cross-session
 * collection-ownership reason.
 */
@Singleton
open class UserResolutionService(
    private val userRepository: UserRepository,
    private val userMappingService: UserMappingService
) {
    private val log = LoggerFactory.getLogger(UserResolutionService::class.java)
    private val passwordEncoder = BCryptPasswordEncoder()

    @Serdeable
    data class UserRef(val id: Long? = null, val email: String? = null)

    /**
     * @param userId  primary key — wins over email when both provided
     * @param email   case-insensitive email; required if userId is null/0
     * @param context short label used only in error messages
     */
    @Transactional
    open fun resolveByIdOrEmail(
        userId: Long?,
        email: String?,
        context: String,
        roles: Set<User.Role>? = null,
    ): User {
        if (userId != null && userId > 0) {
            return userRepository.findById(userId)
                .orElseThrow { NoSuchElementException("$context user not found: id=$userId") }
        }
        val normalizedEmail = email?.trim()?.takeIf { it.isNotEmpty() }
            ?: throw IllegalArgumentException("$context user identifier required (id or email)")

        userRepository.findByEmailIgnoreCase(normalizedEmail).orElse(null)?.let { return it }

        log.info("Creating User row on demand for {} email: {}", context, normalizedEmail)
        val username = resolveUniqueUsername(normalizedEmail.substringBefore("@"))
        val newUser = User(
            username = username,
            email = normalizedEmail,
            passwordHash = passwordEncoder.encode(UUID.randomUUID().toString())!!,
            roles = (roles ?: setOf(User.Role.USER, User.Role.VULN, User.Role.REQ)).toMutableSet(),
            authSource = User.AuthSource.OAUTH
        )
        val saved = try {
            userRepository.save(newUser)
        } catch (e: Exception) {
            // Another request may have created the same email between our check and our insert.
            // Walk the cause chain — Hibernate wraps unique-constraint hits as
            // org.hibernate.exception.ConstraintViolationException nested inside
            // PersistenceException / RollbackException depending on call site.
            val isUniqueRace = generateSequence<Throwable>(e) { it.cause }
                .any { it is ConstraintViolationException }
            if (!isUniqueRace) throw e
            log.info("Race on lazy User create for {} — re-querying", normalizedEmail)
            return userRepository.findByEmailIgnoreCase(normalizedEmail).orElseThrow {
                IllegalStateException("Lazy create failed and email still missing: $normalizedEmail", e)
            }
        }

        // Apply PENDING UserMappings synchronously in this transaction.
        //
        // We deliberately do NOT publish UserCreatedEvent: the default listener
        // (UserMappingService.onUserCreated) is @Async @Transactional, which opens
        // a SEPARATE Hibernate session while ours still owns the new User's
        // `workgroups` PersistentSet. That cross-session collection ownership
        // trips Hibernate's "Found shared references to a collection" check.
        try {
            val applied = userMappingService.applyFutureUserMapping(saved)
            if (applied > 0) {
                log.info("Applied {} pending mapping(s) to lazily-created user: {}", applied, saved.email)
            }
        } catch (e: Exception) {
            log.warn("Failed to apply pending mappings for {}: {}", saved.email, e.message)
        }
        return saved
    }
#!/bin/bash
# scripts/lib/aws-secrets.sh — shared bootstrap for the *aws.sh launchers.
#
# This file is sourced (not executed) by every scripts/*aws.sh launcher. It:
#
#   1. Builds a cron-safe PATH (cron does not source ~/.bashrc / ~/.profile).
#   2. Sources SDKMAN (and nvm, if installed) so SDKMAN-managed java/gradle and
#      nvm-managed node/npm are visible — even under cron / systemd.
#   3. Fetches a single JSON secret from AWS Secrets Manager and exposes a
#      `secman_aws_export_envfile` function that maps secret keys to env vars,
#      mirroring what `pass-cli run --env-file secmanpp.env` does.
#   4. Locates the project root and the CLI shadow JAR for callers that need
#      them.
#
# Public API (functions that callers should use):
#
#   secman_aws_load_secret           Fetches the JSON secret. Stores it in
#                                    SECMAN_AWS_SECRET_JSON. Idempotent.
#   secman_aws_export_envfile        Exports the full pass-cli-equivalent set
#                                    of env vars. Safe to call multiple times.
#   secman_aws_extract <key>         Echoes one value from the secret JSON.
#
# Public variables set by this file:
#   PROJECT_ROOT                     Absolute path to the secman repo root.
#   CLI_JAR                          Path to src/cli/build/libs/cli-0.1.0-all.jar
#
# Configuration env vars consumed:
#   SECMAN_AWS_SECRET_ID             Secrets Manager secret name or ARN.
#                                    Default: secman/dev
#   AWS_REGION / AWS_DEFAULT_REGION  Region for the secret. Default: eu-central-1
#   SDKMAN_DIR                       SDKMAN install root. Default: $HOME/.sdkman
#   NVM_DIR                          nvm install root. Default: $HOME/.nvm
#
# See docs/AWS.md for the canonical secret schema and IAM permissions.

# Guard: only run the bootstrap once per shell, even if multiple launchers
# source this file in the same process.
if [ "${SECMAN_AWS_LIB_LOADED:-}" = "1" ]; then
  return 0 2>/dev/null || exit 0
fi
SECMAN_AWS_LIB_LOADED=1

# --- Cron-safe environment ---------------------------------------------------
: "${HOME:=$(getent passwd "$(id -u)" 2>/dev/null | cut -d: -f6)}"
export HOME

export PATH="${HOME}/.local/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:${PATH:-}"

# Source SDKMAN. SDKMAN's init script touches unset variables, so we relax `-u`
# while sourcing if the caller had it on.
SDKMAN_DIR="${SDKMAN_DIR:-${HOME}/.sdkman}"
if [ -s "${SDKMAN_DIR}/bin/sdkman-init.sh" ]; then
  case "$-" in *u*) _secman_aws_had_u=1; set +u ;; *) _secman_aws_had_u=0 ;; esac
  # shellcheck disable=SC1091
  source "${SDKMAN_DIR}/bin/sdkman-init.sh"
  [ "${_secman_aws_had_u:-0}" = "1" ] && set -u
  unset _secman_aws_had_u
fi

# Source nvm if present (lets callers find node/npm under cron).
NVM_DIR="${NVM_DIR:-${HOME}/.nvm}"
if [ -s "${NVM_DIR}/nvm.sh" ]; then
  case "$-" in *u*) _secman_aws_had_u=1; set +u ;; *) _secman_aws_had_u=0 ;; esac
  # shellcheck disable=SC1091
  source "${NVM_DIR}/nvm.sh" --no-use
  if [ -s "${NVM_DIR}/alias/default" ]; then
    nvm use default >/dev/null 2>&1 || true
  fi
  [ "${_secman_aws_had_u:-0}" = "1" ] && set -u
  unset _secman_aws_had_u
fi

# --- Project layout ----------------------------------------------------------
# BASH_SOURCE[0] is this file; the project root is two levels up
# (scripts/lib/aws-secrets.sh -> ../..).
_SECMAN_AWS_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "${_SECMAN_AWS_LIB_DIR}/../.." && pwd)"
CLI_JAR="${PROJECT_ROOT}/src/cli/build/libs/cli-0.1.0-all.jar"
export PROJECT_ROOT CLI_JAR

# --- AWS Secrets Manager fetch ----------------------------------------------
SECMAN_AWS_SECRET_ID="${SECMAN_AWS_SECRET_ID:-secman/dev}"
SECMAN_AWS_REGION="${AWS_REGION:-${AWS_DEFAULT_REGION:-eu-central-1}}"
SECMAN_AWS_SECRET_JSON=""

secman_aws_require_tools() {
  command -v aws >/dev/null 2>&1 || { echo "ERROR: aws CLI is required. See docs/AWS.md."; return 1; }
  command -v jq  >/dev/null 2>&1 || { echo "ERROR: jq is required. See docs/AWS.md.";       return 1; }
}

secman_aws_load_secret() {
  if [ -n "${SECMAN_AWS_SECRET_JSON:-}" ]; then return 0; fi
  secman_aws_require_tools || return 1
  echo "[aws-secrets] Fetching secret '${SECMAN_AWS_SECRET_ID}' from AWS Secrets Manager (region ${SECMAN_AWS_REGION})..." >&2
  SECMAN_AWS_SECRET_JSON=$(aws secretsmanager get-secret-value \
    --secret-id "${SECMAN_AWS_SECRET_ID}" \
    --region "${SECMAN_AWS_REGION}" \
    --query SecretString \
    --output text) || {
      echo "ERROR: failed to read secret '${SECMAN_AWS_SECRET_ID}' (region ${SECMAN_AWS_REGION})" >&2
      return 1
    }
  if [ -z "${SECMAN_AWS_SECRET_JSON}" ] || [ "${SECMAN_AWS_SECRET_JSON}" = "None" ]; then
    echo "ERROR: empty SecretString for ${SECMAN_AWS_SECRET_ID}" >&2
    return 1
  fi
}

# Echo one value from the secret JSON, or empty if absent.
secman_aws_extract() {
  printf '%s' "${SECMAN_AWS_SECRET_JSON}" | jq -r --arg k "$1" '.[$k] // empty'
}

# Helper: export an env var from a secret key. Skips if the key is missing or
# empty, so optional fields don't clobber whatever's already set.
secman_aws_export() {
  local var="$1" key="$2" val
  val="$(secman_aws_extract "$key")"
  if [ -n "$val" ]; then export "$var=$val"; fi
}

# Export the full set of env vars that secmanpp.env normally provides via
# pass-cli. Mirrors the `key -> env var` mapping the original launchers used.
secman_aws_export_envfile() {
  secman_aws_load_secret || return 1

  # Backend connection / target URL
  secman_aws_export DB_CONNECT                    DB_CONNECT
  secman_aws_export SECMAN_BACKEND_URL            SECMAN_BACKEND_BASE_URL
  secman_aws_export SECMAN_DOMAIN                 SECMAN_BACKEND_BASE_URL
  secman_aws_export SECMAN_HOST                   SECMAN_HOST
  secman_aws_export SECMAN_INSECURE               SECMAN_SSL_ACCEPT_ALL

  # Database (used by some CLI paths that build the JDBC URL themselves)
  secman_aws_export SECMAN_DB_HOST                SECMAN_DB_HOST
  secman_aws_export SECMAN_DB_PORT                SECMAN_DB_PORT
  secman_aws_export SECMAN_DB_NAME                SECMAN_DB_NAME
  secman_aws_export DB_USERNAME                   SECMAN_DB_USER
  secman_aws_export DB_PASSWORD                   SECMAN_DB_PASSWORD

  # Admin + test user identities
  secman_aws_export SECMAN_ADMIN_NAME             SECMAN_ADMIN_NAME
  secman_aws_export SECMAN_ADMIN_PASS             SECMAN_ADMIN_PASS
  secman_aws_export SECMAN_ADMIN_EMAIL            SECMAN_ADMIN_EMAIL
  secman_aws_export SECMAN_USER_NAME              SECMAN_USER_NAME
  secman_aws_export SECMAN_USER_PASS              SECMAN_USER_PASS

  # Auth keys
  secman_aws_export SECMAN_MCP_KEY                SECMAN_MCP_KEY

  # Integrations
  secman_aws_export FALCON_CLIENT_ID              FALCON_CLIENT_ID
  secman_aws_export FALCON_CLIENT_SECRET          FALCON_CLIENT_SECRET
  secman_aws_export FALCON_CLOUD_REGION           FALCON_CLOUD_REGION
  secman_aws_export SECMAN_OPENROUTER_API_KEY     OPENROUTER_API_KEY

  # Application-side AWS credentials. Only override the ambient identity if the
  # secret carries them — leave empty in the secret to fall back to an EC2
  # instance role.
  secman_aws_export AWS_ACCESS_KEY_ID             SECMAN_AWS_ACCESS_KEY_ID
  secman_aws_export AWS_SECRET_ACCESS_KEY         SECMAN_AWS_SECRET_ACCESS_KEY
  secman_aws_export AWS_SESSION_TOKEN             SECMAN_AWS_ACCESS_TOKEN
}

# Fail if the CLI shadow JAR has not been built yet.
secman_aws_require_cli_jar() {
  if [ ! -f "${CLI_JAR}" ]; then
    cat >&2 <<EOF
ERROR: CLI JAR not found at ${CLI_JAR}

Build it first with:
  ./gradlew :cli:shadowJar
EOF
    return 1
  fi

