    fun putMapWithStatus(url: String, body: Any, authToken: String): Pair<Int, Map<*, *>?> {
        val request = HttpRequest.PUT(url, body)
            .header("Authorization", "Bearer $authToken")
            .contentType(MediaType.APPLICATION_JSON)

        return try {
            val response = httpClient.toBlocking().exchange(request, Map::class.java)
            response.status.code to response.body()
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            val status = e.status.code
            val errorBody = try {
                e.response.getBody(Map::class.java).orElse(null)
            } catch (_: Exception) {
                null
            }
            log.warn("PUT {} returned {}: {}", url, status, e.message)
            status to errorBody
        } catch (e: Exception) {
            log.error("PUT {} error: {}", url, e.message)
            -1 to null
        }
    }

    /**
     * Send a DELETE request with JWT authentication, returning both the HTTP
     * status code and the parsed body (mirrors postMapWithStatus/putMapWithStatus).
     */
    fun deleteWithStatus(url: String, authToken: String): Pair<Int, Map<*, *>?> {
        val request = HttpRequest.DELETE<Any>(url)
            .header("Authorization", "Bearer $authToken")

        return try {
            val response = httpClient.toBlocking().exchange(request, Map::class.java)
            response.status.code to response.body()
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            val status = e.status.code
            val errorBody = try {
                e.response.getBody(Map::class.java).orElse(null)
            } catch (_: Exception) {
                null
            }
            log.warn("DELETE {} returned {}: {}", url, status, e.message)
            status to errorBody
        } catch (e: Exception) {
            log.error("DELETE {} error: {}", url, e.message)
            -1 to null
        }
    }

    /**
     * Send a POST request returning raw string body
     */
    fun postString(url: String, body: Any, authToken: String): String? {
        val request = HttpRequest.POST(url, body)
            .header("Authorization", "Bearer $authToken")
            .contentType(MediaType.APPLICATION_JSON)

        return try {
            val response = httpClient.toBlocking().exchange(request, String::class.java)
            response.body()
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            log.error("POST {} failed: {} - {}", url, e.status.code, e.message)
            null
        } catch (e: Exception) {
            log.error("POST {} error: {}", url, e.message)
            null
        }
    }

    /**
     * Send a GET request returning a list of maps (for array responses)
     */
    @Suppress("UNCHECKED_CAST")
    fun getList(url: String, authToken: String): List<Map<String, Any?>>? {
        val request = HttpRequest.GET<Any>(url)
            .header("Authorization", "Bearer $authToken")
            .accept(MediaType.APPLICATION_JSON)

        return try {
            val response = httpClient.toBlocking().exchange(request, String::class.java)
            val body = response.body() ?: return null
            objectMapper.readValue(body, List::class.java) as? List<Map<String, Any?>>
        } catch (e: io.micronaut.http.client.exceptions.HttpClientResponseException) {
            log.error("GET {} failed: {} - {}", url, e.status.code, e.message)
            null
        } catch (e: Exception) {
            log.error("GET {} error: {}", url, e.message)
            null
        }
    }

    fun getObjectMapper(): ObjectMapper = objectMapper
